import {esc} from './weather-tools.js';
import {LOCAL_POLLEN,highPollen,localSea,localSnow,localHour} from './local-weather-rules.js';
const sourcePollen='https://ambiente.provincia.bz.it/it/aria/intervalli-concentrazione';
export function createLocalWeather(ctx){
 let allergy=false;try{allergy=localStorage.getItem('ms-pollen-opt-in')==='true'}catch{}
 const cache=new Map(),pending=new Set();let timer;
 const key=()=>{const p=ctx.get().place;return `${p.latitude},${p.longitude}`};
 const clock=t=>new Date(t).toLocaleString('it-IT',{timeZone:'Europe/Rome',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
 function slot(){return '<div data-local-weather aria-live="polite"></div>'}
 function profile(){return `<section><h2>Pollini nella mia zona</h2><label><input type="checkbox" id="local-pollen-opt" ${allergy?'checked':''}> Sono allergico: mostrami gli aggiornamenti sui pollini</label><details class="info-disclosure"><summary aria-label="Informazioni sui pollini">i</summary><p>Preferenza conservata in questo browser. Le concentrazioni sono stime del modello, non una previsione dei sintomi.</p></details><p id="local-pollen-status" role="status"></p></section>`}
 function line(kind){const row=cache.get(key()+':'+kind);if(!row)return '';if(row.error)return `<p>${kind==='pollen'?'Pollini':kind==='sea'?'Mare':'Quota neve'}: dati non disponibili adesso.</p>`;if(row.status!=='available')return '';
 const d=row.data,old=row.stale||Date.now()-row.at>3600000,stamp=`${esc(row.source)} · dato ${clock((d.hourly.time[localHour(d)]||0)*1000)}${old?' · copia non aggiornata':''}`;
 if(old)return `<p>${kind==='pollen'?'Pollini':kind==='sea'?'Mare':'Quota neve'}: aggiornamento non disponibile. Ultima lettura ${clock(row.at)}.</p>`;
 if(kind==='pollen'){const i=localHour(d),high=highPollen(d);if(i<0||LOCAL_POLLEN.every(([k])=>!Number.isFinite(d.hourly[k]?.[i])))return '<p>Pollini: previsione non disponibile per questa zona o stagione.</p>';if(!high.length)return LOCAL_POLLEN.some(([k])=>!Number.isFinite(d.hourly[k]?.[i]))?'<p>Pollini: dati parziali, non posso verificare tutte le famiglie botaniche.</p>':'';return `<p><strong>Pollini elevati: ${high.map(p=>esc(p.name.toLowerCase())).join(', ')}.</strong> ${high.map(p=>esc(p.name)+' '+Math.round(p.value)+' granuli/m³').join(' · ')}. <small>${stamp}. Soglie indicative per famiglia botanica: <a href="${sourcePollen}" target="_blank" rel="noopener">fonte</a>.</small></p>`}
 if(kind==='sea'){const sea=localSea(d);if(!sea)return '<p>Mare: previsione non disponibile adesso.</p>';return `<p><strong>${sea.height<.5?'Onde sotto mezzo metro.':'Il mare oggi.'}</strong> Onde ${sea.height<1?Math.round(sea.height*100)+' cm':sea.height.toFixed(1)+' m'}${sea.temperature!==null?', acqua '+sea.temperature.toFixed(1)+'°':''}${sea.period!==null?', periodo '+sea.period.toFixed(0)+' s':''}${sea.direction!==null?', onde da '+Math.round(sea.direction)+'°':''}.${sea.rough?' Onde previste di '+sea.rough.height.toFixed(1)+' m alle '+clock(sea.rough.at)+'.':''} <small>${stamp}. Circa ${row.distanceKm} km dalla costa cartografica. <a href="https://open-meteo.com/en/docs/marine-weather-api" target="_blank" rel="noopener">Fonte</a>. Stima al largo, non condizioni della singola spiaggia.</small></p>`}
 const snow=localSnow(d);if(snow)return `<p><strong>Quota neve prevista intorno a ${snow.height} m.</strong> ${clock(snow.at)}${snow.elevation!==null?' · quota del punto nel modello '+Math.round(snow.elevation)+' m':''}. Se sali in quota, controlla condizioni della strada e ordinanze per catene o pneumatici invernali. <small>${esc(row.source)} · <a href="https://open-meteo.com/en/docs/dwd-api" target="_blank" rel="noopener">Fonte</a>. Stima del modello, non quota garantita lungo un percorso.</small></p>`;
 if(!d.hourly.snowfall_height?.some(Number.isFinite))return '<p>Quota neve non disponibile per questa zona. Lo zero termico non viene usato come sostituto.</p>';return '';
 }
 function paint(){document.querySelectorAll('[data-local-weather]').forEach(el=>{el.innerHTML=(allergy?line('pollen'):'')+line('sea')+line('snow');for(const small of el.querySelectorAll('small')){const info=document.createElement('details'),summary=document.createElement('summary');info.className='info-disclosure';summary.textContent='i';summary.setAttribute('aria-label','Fonte e dettagli del dato');info.append(summary);const paragraph=small.closest('p');if(paragraph){small.remove();info.append(small);paragraph.after(info)}else{small.replaceWith(info);info.append(small)}}})}
 async function load(kind){const k=key()+':'+kind;if(pending.has(k)||cache.has(k)&&Date.now()-cache.get(k).checked<900000)return;pending.add(k);const p=ctx.get().place;try{const result=await ctx.api('local-weather/'+kind+'?'+new URLSearchParams({lat:p.latitude,lon:p.longitude}));cache.set(k,{...result,checked:Date.now()})}catch{cache.set(k,{error:true,checked:Date.now()-840000})}finally{pending.delete(k);paint()}}
 function refresh(){paint();if(!document.querySelector('[data-local-weather]')||document.hidden)return;if(allergy)load('pollen');load('sea');const m=Number(new Intl.DateTimeFormat('en',{timeZone:'Europe/Rome',month:'numeric'}).format(Date.now()));if(m<=3||m>=11)load('snow')}
 function bind(){const input=document.querySelector('#local-pollen-opt');if(input)input.onchange=()=>{allergy=input.checked;try{localStorage.setItem('ms-pollen-opt-in',String(allergy));document.querySelector('#local-pollen-status').textContent='Preferenza salvata.'}catch{document.querySelector('#local-pollen-status').textContent='Preferenza valida solo per questa visita.'}refresh()};refresh();if(!timer)timer=setInterval(refresh,60000)}
 return {slot,profile,bind,refresh};
}
